2	//! Where the checker says each prop is declared (ADR 0026 S7a): `parent`, `declarations`, tags and `composes` come from
3	//! its answer, not from the structural prop of the same name. The `declared` fixture, asked of the built-in checker:
4	//!
5	//! - `Button`: `tone` declared in `ButtonProps` in `Button.tsx`, `size` in `BaseProps` in `Base.ts`, each with its
6	//!   tags; it is made of React's `HTMLAttributes` (under an `Omit`) and `RefAttributes`;
7	//! - `Picked`: `disabled` reaches it through `Pick<BaseProps, …>`, a mapped type whose property names no parent, and
8	//!   is still `BaseProps`'s;
9	//! - `Card`: `label` and `count` are members of type literals, which name no interface.
10	
11	use std::collections::BTreeMap;
12	use std::time::Duration;
13	
14	use caliper_docgen_core::pipeline::{PipelineOptions, extract};
15	use caliper_docgen_core::types::semantic::{SemanticOutcome, merge_semantic};
16	use caliper_docgen_core::types::{ExtractionOutput, PropParent};
17	use caliper_docgen_semantic::{SemanticRequest, resolve, targets_of};
18	use camino::Utf8PathBuf;
19	
20	mod support;
21	use support::copy_fixture;
22	
23	struct Project {
24	    _dir: tempfile::TempDir,
25	    root: Utf8PathBuf,
26	}
27	
28	/// The fixture in a scratch directory whose name has an upper-case letter, so a file the checker names lower-cased is
29	/// told from the path on disk.
30	fn project() -> Project {
31	    let dir = tempfile::Builder::new().prefix("Declared").tempdir().unwrap();
